  elseif($action==='upload'){$account=(int)($_POST['account']??0);$f=$_FILES['statement']??null;if(!$f||($f['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>4*1024*1024)throw new RuntimeException('Bitte eine Datei (CSV oder XML, höchstens 4 MB) auswählen.');$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['csv','xml','txt'],true))throw new RuntimeException('Bitte den CSV-Export (oder CAMT-XML) der Volksbank hochladen.');$token=estateStatementPreview($pdo,$admin,$account,(string)file_get_contents($f['tmp_name']));redirect($back.'&proposal='.$token.'#pruefen');}
  elseif($action==='apply'){$n=estateBankApply($pdo,$admin,(string)($_POST['token']??''),!empty($_POST['possible_reviewed']));$_SESSION['app_notice']=$n?($n===1?'1 neuer Umsatz übernommen.':$n.' neue Umsätze übernommen.'):'Keine neuen Umsätze – alles war schon da.';}
