  elseif($action==='hints_clear'){estateClearTenantIban($pdo,$admin,(int)($_POST['tenant_id']??0));$_SESSION['app_notice']='IBAN entfernt.';}
  else throw new RuntimeException('Aktion unbekannt.');
 }catch(Throwable $e){gszUiError($e);}redirect($back.$anchor);}
