<form method="post"><?php gszFields('assign');?><input type="hidden" name="transaction_id" value="<?=(int)$t['id']?>"><label class="sr-only" for="c<?=(int)$t['id']?>">Mieter</label><select id="c<?=(int)$t['id']?>" name="charge_id"><option value="0">Mieter wählen …</option><?php $seen=[];foreach(array_filter([$best,...$x['alternatives']]) as $o){$seen[(int)$o['charge']['id']]=true;?><option value="<?=(int)$o['charge']['id']?>" <?=$o===$best?'selected':''?>><?=e($o['charge']['tenant_name'].' · '.substr($o['charge']['month'],5,2).'/'.substr($o['charge']['month'],0,4).' · offen '.moneyDisplay((int)$o['charge']['open_cents']))?></option><?php }foreach(estateRentLedger($pdo,$month,(int)$a['building_id']) as $c)if(!isset($seen[(int)$c['id']])&&(int)$c['open_cents']>0):?><option value="<?=(int)$c['id']?>"><?=e($c['tenant_name'].' · offen '.moneyDisplay((int)$c['open_cents']))?></option><?php endif?></select><button class="<?=$best?'primary':''?>">Zuordnen</button></form></div><?php endforeach?></section><?php endif?>
